#!/usr/bin/env node
// Bundles server.js, calendar.js, google.js, battery.js, planusage.js, hook.js, statusline.js and setup-hooks.js into one script for the
// app's built-in Node (a Node "single executable application"). The sources stay unchanged: each
// file runs as its own module, and __dirname points at the app's Resources/app folder, where
// index.html, settings.html and google-client.json live.
// Usage: node bundle.js <project-dir> <output.js>
const fs = require("fs");
const path = require("path");

const [src, out] = process.argv.slice(2);
const MODULES = ["server", "calendar", "google", "battery", "planusage", "hook", "statusline", "setup-hooks"];

const wrapped = MODULES.map((name) => {
  const code = fs.readFileSync(path.join(src, `${name}.js`), "utf8").replace(/^#!.*\n/, "");
  return `${JSON.stringify(`./${name}`)}: function (module, exports, require, __filename, __dirname) {\n${code}\n}`;
});

fs.writeFileSync(out, `// Generated by macos/bundle.js. Edit the files in the project folder, not this one.
"use strict";
const path = require("path");
const os = require("os");
const fs = require("fs");

const APP_DIR = process.env.AGENT_FOUDRE_RESOURCES || path.resolve(path.dirname(process.execPath), "../Resources/app");
process.env.CLAUDE_LOCKSCREEN_DIR = process.env.CLAUDE_LOCKSCREEN_DIR || path.join(os.homedir(), ".claude", "agent-foudre");

const sources = {
${wrapped.join(",\n")}
};
const cache = {};
function load(name) {
  if (!(name in sources)) return require(name); // Node's built-in modules
  if (cache[name]) return cache[name].exports;
  const module = (cache[name] = { exports: {} });
  sources[name].call(module.exports, module, module.exports, load, path.join(APP_DIR, name.slice(2) + ".js"), APP_DIR);
  return module.exports;
}

// foudre-node serve                                   the status server (run by launchd)
// foudre-node agent-foudre-hook                       the Claude Code hook (reads the event on stdin)
// foudre-node agent-foudre-statusline                 the status line wrapper (saves plan usage, runs the user's)
// foudre-node setup-hooks <exe> agent-foudre-hook     add the hooks to ~/.claude/settings.json
// foudre-node setup-hooks --uninstall                 remove them
const [mode = "serve", ...rest] = process.argv.slice(2);
if (mode === "agent-foudre-hook") load("./hook");
else if (mode === "agent-foudre-statusline") load("./statusline");
else if (mode === "setup-hooks") {
  process.argv = [process.argv[0], process.argv[1], ...rest];
  load("./setup-hooks");
} else if (mode === "serve") {
  const dir = process.env.CLAUDE_LOCKSCREEN_DIR;
  fs.mkdirSync(dir, { recursive: true });
  const log = fs.createWriteStream(path.join(dir, "server.log"), { flags: "a" });
  const line = (...a) => log.write(\`[\${new Date().toISOString()}] \${a.map(String).join(" ")}\\n\`);
  console.log = console.info = console.warn = console.error = line;
  process.on("uncaughtException", (e) => { line("uncaught:", e && e.stack || e); log.end(() => process.exit(1)); });
  load("./server");
} else {
  process.stderr.write(\`Unknown mode: \${mode}\\n\`);
  process.exit(1); // not 2: Claude Code reads a hook's exit 2 as "block this tool call"
}
`);
console.log(out);
